query:
query CombinedFindManyRecords($filterTask: TaskFilterInput, $filterNote: NoteFilterInput, $orderByTask: [TaskOrderByInput], $orderByNote: [NoteOrderByInput], $afterTask: String, $beforeTask: String, $firstTask: Int, $lastTask: Int, $afterNote: String, $beforeNote: String, $firstNote: Int, $lastNote: Int) {
  tasks(
    filter: $filterTask
    orderBy: $orderByTask
    after: $afterTask
    before: $beforeTask
    first: $firstTask
    last: $lastTask
  ) {
    edges {
      node {
        __typename
        id
        title
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
  notes(
    filter: $filterNote
    orderBy: $orderByNote
    after: $afterNote
    before: $beforeNote
    first: $firstNote
    last: $lastNote
  ) {
    edges {
      node {
        __typename
        id
        title
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
}
